INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_JM_MALKHUT_ZOHAR2','ENT_JM_MALKHUT','SRC_ZOHAR','The Zohar (Soncino edition)','The Zohar (Soncino edition)','This is why Adam, who is Israel, is closely linked with the Torah, of which it is said, "It is a tree of life to those who take hold on it"; this tree is the Matron, the Sefirah Malkhuth (Kingship), through their connection with which Israel are called "sons of kings". On this account God said, "It is not good that the man should be alone; I will make him an help meet for him" (Gen. II, 18).','Sperling & Simon',1934,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_JM_SEFIROT_ZOHAR2','ENT_JM_SEFIROT','SRC_ZOHAR','The Zohar (Soncino edition)','The Zohar (Soncino edition)','That is to say, through the Sefiroth on the right side I make alive, and through the Sefiroth on the left side I kill; but if the Central Column does not concur, sentence cannot be passed, since they form a court of three.','Sperling & Simon',1934,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_JM_ATIKA_KADISHA_ZOHAR2','ENT_JM_ATIKA_KADISHA','SRC_ZOHAR','The Zohar (Soncino edition)','The Zohar (Soncino edition)','For so we have learnt, that when the Holy One, blessed be He, looks upon the works of men and sees that they are good, then the Ancient Holy One is revealed in the Small of Countenance, and all the countenance of the latter beholds the hidden countenance and is wholly blessed, since they look at one another directly without turning to the right or left, Soncino Zohar, Vayikra, Section 3, Page 15b and they water one another until all worlds are blessed and','Sperling & Simon',1934,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_JM_BERIAH_ZOHAR2','ENT_JM_BERIAH','SRC_ZOHAR','The Zohar (Soncino edition)','The Zohar (Soncino edition)','In the Zohar itself the worlds of Aziluth and Beriah are mentioned only occasionally, the others hardly at all.] Through this hierarchy an emanation of the Divine Presence is conveyed to earth, just as, on the other hand, the prayer of human beings is conveyed up to heaven. The Shekinah originally rested on the Tabernacle and Temple, but even now it accompanies the wise, especially when three study together.','Sperling & Simon',1934,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_JM_HOKHMAH_ZOHAR2','ENT_JM_HOKHMAH','SRC_ZOHAR','The Zohar (Soncino edition)','The Zohar (Soncino edition)','The names given to the grades are the same as those given in Cabbalist literature to the SefirothKether,.Hokhmah, Binah, then Hesed, etc. For Wisdom and Understanding one can perceive a certain reason; the rest seem more or less fanciful, and no reason for them is given in the Zohar. It should be observed that, strictly speaking, all these are names of God, regarded as first cause.','Sperling & Simon',1934,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_JM_LILITH_ZOHAR2','ENT_JM_LILITH','SRC_ZOHAR','The Zohar (Soncino edition)','The Zohar (Soncino edition)','As soon as he is there, the breath of him who is the Single one (Samael),.who had to be separated from his feminine counterpart (Lilith), and who walks after the manner of a.serpent, breathes on him, and straightway he leaves that mighty rock and, wandering lonely forth, begins to.roam the world until he shall find a "redeemer" through whose agency he can return to this earth.','Sperling & Simon',1934,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_JM_NAAMAH_ZOHAR2','ENT_JM_NAAMAH','SRC_ZOHAR','The Zohar (Soncino edition)','The Zohar (Soncino edition)','A female came with him who was called Naamah, from whom issued other spirits and demons; these hover in the air and tell things to those others below. This Tubal Cain produced weapons of war, and this Naamah clung to her own side, and she still exists, having her abode among the waves of the great sea. She goes forth and makes sport with men and conceives from them through their lustful dreams.','Sperling & Simon',1934,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_JM_TIFERET_ZOHAR2','ENT_JM_TIFERET','SRC_ZOHAR','The Zohar (Soncino edition)','The Zohar (Soncino edition)','The Sefirah Tifereth. BODY. The Sefirah Tifereth. HUSBAND. The divine grade called.Hokmah (Wisdom). ISRAEL. grades. A name given to the highest of the divine CENTRAL PILLAR. A name for the Sef rah Tifereth, JUBILEE. The supernal world; Moses as distinguished from Jacob. which unites the Right and the Left. CHARIOT. That which God directly controls. KING. The highest of the divine grades. CHIEFTAINS. The celestial chiefs and guardians KLIFOTH (lit.','Sperling & Simon',1934,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_JM_ZADKIEL_ZOHAR2','ENT_JM_ZADKIEL','SRC_ZOHAR','The Zohar (Soncino edition)','The Zohar (Soncino edition)','e with burning fire; he gores and tramples with his under him two chieftains, Zophiel and Zadkiel. When feet ruthlessly. When he moos there emerge out of the hollow of the great abyss numerous spirits of wrath who proceed in front in a chorus of shrieking. Seven fiery rivers flow in front of him, and when thirsty he draws up a whole riverful at one gulp. Yet this river is straightway filled again as before, unfailingly.','Sperling & Simon',1934,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
